package id.imperial.shop; import org.bukkit.command.*;public final class AdminCommand implements CommandExecutor{final ImperialShopPlugin p;final ShopService s;AdminCommand(ImperialShopPlugin p,ShopService s){this.p=p;this.s=s;}public boolean onCommand(CommandSender c,Command cmd,String l,String[] a){if(!c.hasPermission("imperialshop.admin")){c.sendMessage("§cTidak memiliki izin.");return true;}if(a.length>0&&a[0].equalsIgnoreCase("reload")){p.reloadPlugin();c.sendMessage("§aImperialShop berhasil di-reload.");return true;}c.sendMessage("§e/imperialshop reload");return true;}}